@section('scripts')
<script>
const usersBaseUrl = '{{ url("admin/users") }}', rolesBaseUrl = '{{ url("admin/roles") }}';
const userModal = document.getElementById('userModal'), roleModal = document.getElementById('roleModal');
userModal.addEventListener('show.bs.modal', event => { if (event.relatedTarget) resetUserForm(); });
roleModal.addEventListener('show.bs.modal', event => { if (event.relatedTarget) resetRoleForm(); });
document.addEventListener('click', function (event) {
    const userButton = event.target.closest('.btn-edit-user');
    if (userButton) { const form = document.getElementById('userForm'); form.action = `${usersBaseUrl}/${userButton.dataset.id}`; document.getElementById('userName').value = userButton.dataset.name; document.getElementById('userEmail').value = userButton.dataset.email; const password = document.getElementById('userPassword'); password.value = ''; password.name = 'new_password'; password.required = false; password.placeholder = 'Leave empty to keep the current password'; document.getElementById('passwordHelp').textContent = 'Leave empty to keep the current password.'; document.querySelector('.password-required').classList.add('d-none'); document.getElementById('userRole').value = userButton.dataset.roleId || ''; document.getElementById('userModalLabel').textContent = `Edit user: ${userButton.dataset.name}`; document.getElementById('userSubmitLabel').textContent = 'Save changes'; document.getElementById('btnDeleteUser').classList.remove('d-none'); document.getElementById('btnDeleteUser').dataset.name = userButton.dataset.name; document.getElementById('deleteUserForm').action = `${usersBaseUrl}/${userButton.dataset.id}/delete`; bootstrap.Modal.getOrCreateInstance(userModal).show(); }
    const roleButton = event.target.closest('.btn-edit-role');
    if (roleButton) { const form = document.getElementById('roleForm'); form.action = `${rolesBaseUrl}/${roleButton.dataset.id}`; document.getElementById('roleName').value = roleButton.dataset.name; document.getElementById('roleDescription').value = roleButton.dataset.description || ''; const selected = (roleButton.dataset.permissionIds || '').split(',').filter(Boolean); document.querySelectorAll('.role-permission-check').forEach(checkbox => checkbox.checked = selected.includes(checkbox.value)); document.getElementById('roleModalLabel').textContent = `Edit role: ${roleButton.dataset.name}`; document.getElementById('roleSubmitLabel').textContent = 'Save role'; bootstrap.Modal.getOrCreateInstance(roleModal).show(); }
});
document.getElementById('btnDeleteUser').addEventListener('click', function () { const name = this.dataset.name || 'this user', remove = () => document.getElementById('deleteUserForm').submit(); if (typeof Swal === 'undefined') { if (window.confirm(`Delete ${name}? This action cannot be undone.`)) remove(); return; } Swal.fire({title:`Delete ${name}?`,text:'This action cannot be undone.',icon:'warning',showCancelButton:true,confirmButtonText:'Yes, delete user',cancelButtonText:'Cancel',confirmButtonColor:'#b44955',cancelButtonColor:'#667085'}).then(result => { if (result.isConfirmed) remove(); }); });
function resetUserForm() { const form = document.getElementById('userForm'); form.action = '{{ route('users.store') }}'; form.reset(); const password = document.getElementById('userPassword'); password.name = 'password'; password.required = true; password.placeholder = ''; document.getElementById('passwordHelp').textContent = 'Minimum 8 characters'; document.querySelector('.password-required').classList.remove('d-none'); document.getElementById('userModalLabel').textContent = 'Add user'; document.getElementById('userSubmitLabel').textContent = 'Create user'; document.getElementById('btnDeleteUser').classList.add('d-none'); }
function resetRoleForm() { const form = document.getElementById('roleForm'); form.action = '{{ route('roles.store') }}'; form.reset(); document.getElementById('roleModalLabel').textContent = 'Create role'; document.getElementById('roleSubmitLabel').textContent = 'Save role'; }
function togglePwd(inputId, button) { const input = document.getElementById(inputId), icon = button.querySelector('i'); input.type = input.type === 'password' ? 'text' : 'password'; icon.className = input.type === 'password' ? 'bx bx-show' : 'bx bx-hide'; }
</script>
@endsection
